### `elided()` full body — `layout.rs:660-704`
```rust
fn elided(line: &str, marker: usize, kind: Kind, flags: &[u16]) -> Vec<(usize,usize)> {
    let mut out = Vec::new();
    if matches!(kind, Kind::Quote|Kind::Bullet|Kind::Ordered|Kind::Task(_)) {
        let indent = line.len()-line.trim_start_matches([' ','\t']).len();
        if marker > indent { out.push((indent, marker)); }
    }
    if matches!(kind, Kind::Task(true)) { return out; }
    let links: Vec<Range<usize>> = md::links(line).into_iter().map(|(r,_)|r).collect();
    let image = md::image(line).map(|(r,_)|r);
    let mut hide = |r: Range<usize>| {
        if image.is_none_or(|(s,_)| s.end<=r.start||r.end<=s.start)
        && links.iter().all(|l| l.end<=r.start||r.end<=l.start)
        && md::comments(line).iter().all(|(w,_,_)| w.end<=r.start||r.end<=w.start)
        && !md::callout(line).is_some_and(|c| c.contains(&r.start)) { out.push((r.start,r.end)); }
    };
    let mut i=0;
    while i<flags.len() {
        if flags[i]&md::DIM!=0 { let mut j=i+1; while j<flags.len()&&flags[j]&md::DIM!=0 {j+=1;} hide(i..j); i=j; }
        else { i+=1; }
    }
    out
}
```
