## 4. `src/views/editor/blocks.rs:147-182` — `hand_at` full body
```rust
pub(super) fn hand_at(&self, at:Point<Pixels>, held:gpui::Modifiers)->Option<CursorStyle> {
    if self.stale() { return self.hand; }
    if self.moving.is_some() { return Some(CursorStyle::ClosedHand); }
    if !self.viewport.contains(&at) { return None; }
    if self.embed_at(at).is_some_and(|(..,on_label)| on_label) { return Some(PointingHand); }
    if let Some((_,part))=self.part_at(at) { return Some(match part {
        Part::JoinCol(_)|Part::JoinRow(_)=>PointingHand,
        Part::Col(_)|Part::Row(_)|Part::Corner=>OpenHand }); }
    if self.rows.is_empty() { return None; }
    if !held.secondary() && self.checkbox_at(at).is_some() { return Some(PointingHand); }
    let i=self.index_at(at); let lr=self.line_range(i);
    let (line,col)=(&self.content[lr.clone()],i-lr.start);
    if held.secondary() && md::links(line).into_iter().any(|(r,_)|r.contains(&col)) {
        return Some(CursorStyle::PointingHand);
    }
    let (kind,marker)=md::classify(line,self.in_code(lr.start));
    (matches!(kind,Kind::Task(_)) && col+4>=marker && col<marker).then_some(PointingHand)
}
```
